394	func TestCompactWithSnapshotsOpenThenReclaimAfterClose(t *testing.T) {
395		s := openStore(t, tempDir(t))
396		if err := s.Put("k", []byte("v1")); err != nil {
397			t.Fatal(err)
398		}
399		old, err := s.Snapshot()
400		if err != nil {
401			t.Fatal(err)
402		}
403		if err := s.Put("k", []byte("v2")); err != nil {
404			t.Fatal(err)
405		}
406	
407		// Snapshot open: disk is still reclaimed, pinned view still served.
408		if err := s.Compact(); err != nil {
409			t.Fatal(err)
410		}
411		if got, ok := old.Get("k"); !ok || string(got) != "v1" {
412			t.Fatalf("pinned v1: %q ok=%v", got, ok)
413		}
414		if got, ok, _ := s.Get("k"); !ok || string(got) != "v2" {
415			t.Fatalf("latest v2: %q ok=%v", got, ok)
416		}
417	
418		if err := old.Close(); err != nil {
419			t.Fatal(err)
420		}
421		// A later snapshot sees only v2; compaction again stays error-free.
422		young, err := s.Snapshot()
423		if err != nil {
424			t.Fatal(err)
425		}
426		if _, ok := young.Get("k"); !ok {
427			t.Fatal("young snapshot misses k")
428		}
429		if err := s.Compact(); err != nil {
430			t.Fatal(err)
431		}
432		if got, ok := young.Get("k"); !ok || string(got) != "v2" {
433			t.Fatalf("young snapshot changed: %q ok=%v", got, ok)
434		}
435		young.Close()
436	}
