package snapshot

import (
	"bufio"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"io"
	"os"
	"sort"
)

// On-disk checkpoint: the complete committed state at one instant frozen into
// a single self-describing file, so reopening can seed memory from it and
// replay only the WAL tail written afterwards instead of the whole log.
//
// Layout, little-endian:
//
//	magic       uint32   checkpointMagic ("SNCK")
//	version     uint32   checkpointVersion1
//	seq         uint64   highest commit sequence handed out at capture time
//	snapshots   uint64   cumulative number of snapshots handed out
//	walOffset   uint64   WAL byte offset the checkpoint cuts at; only strictly
//	                     later WAL frames belong to the post-checkpoint tail
//	entryCount  uint32   number of terminal key/value entries that follow
//	entries     [entryCount]entry
//	crc         uint32   IEEE CRC-32 of every preceding byte
//
// One entry is flags byte (0 = put, 1 = tombstone), uint32 keyLen, uint32
// valLen, key, value. A checkpoint describes terminal state only, so every
// key appears exactly once: a put carries its final value (empty values
// included) and a tombstone carries no value.
//
// The file is an all-or-nothing artifact: it is built under a temporary name,
// forced whole with one fsync, and only then renamed into place. Missing,
// truncated, checksum-bad or unknown-version files are rejected outright and
// recovery silently falls back to replaying the WAL alone; a half checkpoint
// is never loaded as state.
const (
	checkpointName    = "snapshot.ckpt"
	checkpointTmpName = "snapshot.ckpt.tmp"
	// legacyCheckpointNames are discarded on open: these names were never
	// valid checkpoints in any released format, so any file bearing one is
	// stale debris, never something replay could need.
	legacyCheckpointNames = ""

	checkpointMagic   uint32 = 0x53434b54 // "TCKS" read byte order; see below
	checkpointVersion1 uint32 = 1

	checkpointHeaderSize = 4 + 4 + 8 + 8 + 8 + 4
	ckptFlagPut    byte = 0
	ckptFlagDelete byte = 1
)

