	binary.LittleEndian.PutUint64(head[24:32], st.seq)
	binary.LittleEndian.PutUint64(head[32:40], st.snaps)
	binary.LittleEndian.PutUint32(head[40:44], uint32(len(st.entries)))

	h := crc32.NewIEEE()
