		return err
	}
	h.Write(head)

	ehdr := make([]byte, 1+4+4)
	for _, e := range st.entries {
		if len(e.key) > maxRecord || len(e.value) > maxRecord {
			return errors.New("snapshot: checkpoint entry too large")
