	binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
	if _, err = w.Write(crcb[:]); err != nil {
		return err
	}
	if err = w.Flush(); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	return f.Close()
}

